public class HappensBeforeDemonstration {
    private volatile boolean initialized = false;
    private int data = 0;

    public void writerThread() {
        data = 42;               // (1) Normal write
        initialized = true;      // (2) Volatile write (Establishes Happens-Before edge)
    }

    public void readerThread() {
        if (initialized) {       // (3) Volatile read
            // (4) Because of transitive happens-before, data == 42 is guaranteed here
            System.out.println("Data: " + data);
        }
    }
}
